using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using RaceDay.Api.Data;using RaceDay.Api.DTOs;using RaceDay.Api.Models;
namespace RaceDay.Api.Controllers;
[ApiController,Route("api/results")]
public class ResultsController(RaceDayContext db):ControllerBase{
 /// <summary>Participants can only see their own results. Organisers can see all results.</summary>
 [HttpGet,Authorize(Roles="Participant,Organiser"),ProducesResponseType(typeof(IEnumerable<ResultResponse>),200)] public async Task<IActionResult> All(){var q=Query();if(User.IsInRole("Participant")){var id=User.CurrentUserId();q=q.Where(x=>x.Enrolment!.ParticipantID==id);}return Ok(await q.Select(ToDto()).ToListAsync());}
 [HttpGet("mine"),Authorize(Roles="Participant"),ProducesResponseType(typeof(IEnumerable<ResultResponse>),200)] public async Task<IActionResult> Mine(){var id=User.CurrentUserId();return Ok(await Query().Where(x=>x.Enrolment!.ParticipantID==id).Select(ToDto()).ToListAsync());}
 /// <summary>Record or update the finish time and position for an enrolment.</summary>
 [HttpPut("enrolment/{enrolmentId:int}"),Authorize(Roles="Organiser"),ProducesResponseType(typeof(ResultResponse),200),ProducesResponseType(404)] public async Task<IActionResult> Record(int enrolmentId,ResultRequest r){if(r.Status is not ("Recorded" or "Disqualified" or "DidNotFinish"))return BadRequest(new{message="Status must be Recorded, Disqualified or DidNotFinish."});if(r.Position.HasValue&&r.Position.Value<1)return BadRequest(new{message="Position must be positive."});if(r.FinishTime.HasValue&&r.FinishTime.Value<TimeSpan.Zero)return BadRequest(new{message="Finish time cannot be negative."});var enrol=await db.Enrolments.Include(x=>x.Participant).Include(x=>x.EventCategory).ThenInclude(x=>x!.Event).Include(x=>x.EventCategory).ThenInclude(x=>x!.Category).SingleOrDefaultAsync(x=>x.EnrolmentID==enrolmentId);if(enrol is null)return NotFound(new{message="Enrolment not found."});var result=await db.Results.SingleOrDefaultAsync(x=>x.EnrolmentID==enrolmentId);if(result is null){result=new RaceResult{EnrolmentID=enrolmentId};db.Results.Add(result);}result.FinishTime=r.FinishTime;result.Position=r.Position;result.Status=r.Status;result.RecordedAt=DateTime.UtcNow;await db.SaveChangesAsync();return Ok(new ResultResponse(result.ResultID,enrolmentId,enrol.ParticipantID,$"{enrol.Participant!.FirstName} {enrol.Participant.LastName}",enrol.EventID,enrol.EventCategory!.Event!.EventName,enrol.EventCategory.Category!.CategoryName,result.FinishTime,result.Position,result.Status,result.RecordedAt));}
 private IQueryable<RaceResult> Query()=>db.Results.AsNoTracking().Include(x=>x.Enrolment).ThenInclude(x=>x!.Participant).Include(x=>x.Enrolment).ThenInclude(x=>x!.EventCategory).ThenInclude(x=>x!.Event).Include(x=>x.Enrolment).ThenInclude(x=>x!.EventCategory).ThenInclude(x=>x!.Category);
 private static System.Linq.Expressions.Expression<Func<RaceResult,ResultResponse>> ToDto()=>x=>new ResultResponse(x.ResultID,x.EnrolmentID,x.Enrolment!.ParticipantID,x.Enrolment.Participant!.FirstName+" "+x.Enrolment.Participant.LastName,x.Enrolment.EventID,x.Enrolment.EventCategory!.Event!.EventName,x.Enrolment.EventCategory.Category!.CategoryName,x.FinishTime,x.Position,x.Status,x.RecordedAt);
}
